#!/usr/bin/env python3
from pathlib import Path
from html import escape
import json, shutil, os
ROOT=Path(__file__).resolve().parents[1]; OUT=Path(os.environ.get('SCREENQR_SITE_OUTPUT',str(ROOT/'website/dist'))); BASE=os.environ.get('SCREENQR_SITE_URL','https://kunilingvistador.github.io/ScreenQR/'); REPO='https://github.com/kunilingvistador/ScreenQR'; VERSION='0.2.0'; DOWNLOAD=REPO+'/releases/download/v0.2.0-beta/ScreenQR-0.2.0-macos.dmg'
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir(parents=True); shutil.copytree(ROOT/'website/assets',OUT/'assets');(OUT/'.nojekyll').touch()
COPY={
'ru':dict(lang='English',switch='en/',nav=['Как работает','Установка','Инструкции'],source='GitHub',skip='Перейти к содержанию',eyebrow='Маленькая утилита для macOS',h1='QR на экране?',h2='Откройте его на Mac.',lead='Нажмите значок в строке меню, выделите код — посмотрите адрес и откройте ссылку. Без телефона и сохранения скриншотов.',download='Скачать для Mac',demo='Посмотреть, как работает',meta='Бесплатно · macOS 14+ · Apple Silicon и Intel',beta='Бета 0.2.0 · без нотариализации Apple',demoLabel='Интерактивная демонстрация',sample='Ссылка на экране',sampleNote='Демонстрационный QR · example.com',found='QR распознан',open='Открыть',copy='Скопировать',demoNote='Нажмите значок QR в макете. Это демонстрация, а не доступ к вашему экрану.',stepsTitle='Увидели. Выделили. Открыли.',steps=[('Нажмите значок','ScreenQR живёт в строке меню. Один клик запускает сканирование. Свою горячую клавишу можно назначить в настройках.'),('Выделите QR','Экран слегка затемнится. Обведите код целиком, оставив немного пространства по краям. Esc отменяет выделение.'),('Проверьте адрес','Домен заметен сразу, полный адрес доступен до перехода. Откройте ссылку в привычном браузере или скопируйте результат.')],inputsTitle='Откуда бы ни был QR.',inputs=[('Прямо с экрана','Сайт, PDF, презентация, видеозвонок. Если QR виден на экране, его можно выделить.'),('Из картинки или буфера','Правый клик по значку открывает дополнительные действия. Изображение можно перетащить в настройки или прочитать из буфера.')],privacyTitle='Распознаётся на вашем Mac.',privacyText='ScreenQR использует Apple Vision. Снимки не отправляются на сервер и не сохраняются приложением. Истории сканирований нет. Переход по ссылке происходит только после вашего нажатия.',privacyLink='Данные и разрешения',installTitle='Первый запуск — по шагам.',install=['Скачайте DMG, откройте его и перенесите ScreenQR в «Программы».','Запустите ScreenQR. В строке меню появится значок QR.','При первом сканировании разрешите запись экрана в Системных настройках → Конфиденциальность и безопасность. Перезапустите приложение, если macOS попросит.'],installNote='Это открытая бета без Developer ID и нотариализации Apple. Если macOS блокирует запуск, прочитайте инструкцию установки и проверьте источник загрузки. Мы не предлагаем отключать защиту системы.',installLink='Установка и доступ к экрану',guidesTitle='Ответы на конкретные задачи.',faqTitle='Что стоит знать.',faq=[('Нужно сохранять скриншот?','Нет. Основной способ — выделить QR прямо на экране. Картинки и буфер обмена доступны как дополнительные способы.'),('Ссылка откроется автоматически?','Нет. Сначала вы увидите результат, затем сами нажмёте «Открыть». ScreenQR не проверяет репутацию сайта; посмотрите на домен и полный адрес.'),('Какой браузер используется?','Браузер по умолчанию, выбранный в macOS. Можно скопировать адрес и открыть его в другом.'),('Работает с текстом и Wi-Fi?','Да. Такие данные можно скопировать. ScreenQR не подключает Mac к сети и не импортирует контакт автоматически.'),('Есть горячая клавиша?','Назначается в настройках. По умолчанию выключена. Нужны минимум два модификатора, включая Command или Control; занятые системные сочетания не принимаются.')],relatedTitle='Ещё одна небольшая утилита.',relatedText='Работаете с несколькими окнами Chrome? ProfileDock даёт им отдельные ярлыки в Dock.',relatedLink='Посмотреть ProfileDock',footer='Независимый открытый проект для Mac',title='ScreenQR — сканер QR-кодов с экрана Mac',description='Сканируйте QR прямо с экрана Mac: значок в строке меню, выделение области, просмотр адреса и открытие в браузере. Бесплатная утилита для macOS 14+.'),
'en':dict(lang='Русский',switch='',nav=['How it works','Install','Guides'],source='GitHub',skip='Skip to content',eyebrow='A small utility for macOS',h1='QR on your screen?',h2='Open it on your Mac.',lead='Click the menu bar icon, select the code, inspect the address and open the link. No phone or saved screenshots needed.',download='Download for Mac',demo='See how it works',meta='Free · macOS 14+ · Apple Silicon and Intel',beta='Beta 0.2.0 · not notarized by Apple',demoLabel='Interactive demonstration',sample='A link on your screen',sampleNote='Example QR · example.com',found='QR code found',open='Open',copy='Copy',demoNote='Click the QR icon in the mock desktop. This demo does not access your screen.',stepsTitle='See it. Select it. Open it.',steps=[('Click the icon','ScreenQR lives in your menu bar. One click starts a scan. Assign your own keyboard shortcut in Settings.'),('Select the QR','The screen dims slightly. Select the entire code, including a small margin around its edges. Esc cancels selection.'),('Check the address','The domain stands out and the full address is available before opening. Open it in your default browser or copy the result.')],inputsTitle='Wherever the QR lives.',inputs=[('Directly on screen','A website, PDF, presentation or video call. If the code is visible, you can select it.'),('An image or your clipboard','Right-click the icon for additional actions. Drop an image into Settings or read an image from your clipboard.')],privacyTitle='Read on your Mac.',privacyText='ScreenQR uses Apple Vision. The app does not upload or save screenshots. It keeps no scan history. A link opens only after you click Open.',privacyLink='Data and permissions',installTitle='Your first launch, step by step.',install=['Download the DMG, open it and drag ScreenQR into Applications.','Launch ScreenQR. A QR icon appears in the menu bar.','For your first screen scan, allow screen recording in System Settings → Privacy & Security. Restart the app if macOS asks.'],installNote='This open-source beta has no Developer ID signature or Apple notarization. If macOS blocks launch, read the install guide and verify the download source. We do not recommend disabling system protections.',installLink='Installation and screen access',guidesTitle='Help with a specific task.',faqTitle='Good questions.',faq=[('Do I need to save a screenshot?','No. Select the QR directly on your screen. Images and clipboard are optional additional inputs.'),('Will links open automatically?','No. Inspect the result and click Open yourself. ScreenQR does not check website reputation; review the domain and full address.'),('Which browser opens?','The default browser selected in macOS. You can copy the address to use another browser.'),('What about text and Wi-Fi QR codes?','Their contents can be copied. ScreenQR does not connect your Mac to a network or import a contact automatically.'),('Can I use a keyboard shortcut?','Assign one in Settings. It is off by default. Use at least two modifiers, including Command or Control; reserved system shortcuts are rejected.')],relatedTitle='Another small Mac utility.',relatedText='Work with several Chrome windows? ProfileDock gives them separate Dock shortcuts.',relatedLink='Explore ProfileDock',footer='An independent open-source Mac utility',title='ScreenQR — QR scanner for your Mac screen',description='Scan QR codes directly from your Mac screen. Menu bar access, area selection, address preview and opening in your default browser. Free for macOS 14+.')}
GUIDES={
'scan-qr-from-pdf':{'ru':('Как сканировать QR-код из PDF на Mac','Откройте PDF и выделите код на экране — сохранять картинку из документа не нужно.', [('Откройте страницу с QR','Используйте «Просмотр», браузер или любое приложение для PDF. Перейдите на страницу, где виден код. ScreenQR считывает видимую область экрана, а не импортирует PDF.'),('Увеличьте код','Мелкий или размытый код сложнее распознать. Увеличьте масштаб так, чтобы квадраты были различимы и весь код помещался на экране.'),('Выделите и проверьте','Нажмите значок ScreenQR, обведите весь QR вместе с белой рамкой. В карточке проверьте домен и полный адрес. Нажмите «Открыть» или «Скопировать».')]),'en':('How to scan a QR code from a PDF on Mac','Open the PDF and select the code on screen. You do not need to extract an image.', [('Open the page containing the QR','Use Preview, your browser or another PDF reader. ScreenQR reads the visible screen area; it does not import the PDF file.'),('Enlarge the code','Small or blurred codes are harder to recognize. Zoom in until the squares are distinct and the entire code still fits on screen.'),('Select and inspect','Click the ScreenQR icon and select the entire QR, including its white margin. Review the domain and full address in the result card, then Open or Copy.')])},
'scan-qr-from-screenshot':{'ru':('Как прочитать QR-код со скриншота на Mac','Если картинка уже открыта, выделите QR прямо на экране. Для картинки в буфере есть отдельное действие.', [('Когда скриншот виден','Откройте картинку там, где вам удобно. Нажмите значок ScreenQR и выделите QR. Не нужно загружать скриншот на сайт или пересылать его на телефон.'),('Когда картинка в буфере','Скопируйте именно изображение, а не адрес картинки. Нажмите правой кнопкой на значок ScreenQR и выберите «Из буфера обмена». Приложение прочитает изображение локально.'),('Когда картинка — файл','Откройте настройки ScreenQR и перетащите файл в область для изображений. Можно также выбрать «Открыть изображение» в меню. Поддерживаются обычные форматы PNG, JPEG и HEIC.'),('Если результата нет','Убедитесь, что скопировано изображение и QR не обрезан. Для мелкого кода увеличьте исходную картинку, затем выделите код с рамкой.')]),'en':('How to read a QR code from a screenshot on Mac','Select an already visible QR on screen, or use the clipboard action for a copied image.', [('If the screenshot is visible','Open the image wherever convenient. Click ScreenQR and select the QR. There is no need to upload a screenshot to a website or send it to your phone.'),('If the image is in your clipboard','Copy the image itself, rather than its web address. Right-click the ScreenQR icon and choose Read clipboard image. Recognition happens locally.'),('If you have an image file','Open ScreenQR Settings and drop the file in the image area, or choose Open image from the menu. Common PNG, JPEG and HEIC images are supported.'),('If no result appears','Check that your clipboard contains an image and that the QR is not cropped. Enlarge a small source image and select the complete code with its margin.')])},
'screen-recording-permission':{'ru':('Установка ScreenQR и разрешение записи экрана','Доступ нужен, чтобы считать QR из выделенной области. Приложение не записывает видео или звук.', [('Установите приложение','Скачайте DMG из официального выпуска GitHub. Откройте его, перетащите ScreenQR в «Программы» и запускайте эту копию. Не держите одновременно несколько разных сборок.'),('Подтверждение macOS','Текущая бета подписана локальной ad-hoc подписью, без Developer ID и нотариализации. Поэтому macOS может блокировать первый запуск. Проверяйте адрес репозитория и контрольную сумму из выпуска. Следуйте стандартному подтверждению macOS только если доверяете этой сборке; не отключайте Gatekeeper целиком.'),('Разрешите доступ при сканировании','Нажмите «Сканировать». Если доступа нет, ScreenQR покажет объяснение и кнопку настроек. В Конфиденциальности и безопасности найдите «Запись экрана» или «Запись экрана и системного аудио» и включите ScreenQR. Название зависит от версии macOS.'),('Если разрешение включено, но захват не работает','Завершите ScreenQR, убедитесь, что запускаете ту же копию из «Программ», и откройте снова. После замены тестовой сборки macOS иногда требует выдать доступ заново. Не сбрасывайте разрешения остальных приложений.'),('Можно ли отозвать доступ?','Да, выключите ScreenQR на той же странице настроек. Сканирование экрана перестанет работать, но чтение файлов и изображений из буфера не требует этого разрешения.')]),'en':('Install ScreenQR and allow screen recording on Mac','Screen access lets ScreenQR read a selected area. The app does not record video or audio.', [('Install the application','Download the DMG from the official GitHub release. Open it, drag ScreenQR into Applications and launch that copy. Avoid running several different builds at once.'),('macOS launch confirmation','This beta uses an ad-hoc signature and has no Developer ID signature or Apple notarization. macOS may block the first launch. Verify the repository address and the release checksum. Use the standard macOS confirmation only if you trust this build; do not disable Gatekeeper globally.'),('Allow access when scanning','Click Scan. Without access, ScreenQR explains the permission and opens Settings. Under Privacy & Security, find Screen Recording or Screen & System Audio Recording and enable ScreenQR. The label varies by macOS version.'),('If access is enabled but capture fails','Quit ScreenQR, check that you are launching the same copy in Applications, then open it again. Replacing a development build may require granting access again. Do not reset permissions for other apps.'),('Can I revoke access?','Yes. Disable ScreenQR on the same Settings page. Screen scanning will stop, while reading image files and clipboard images does not require this permission.')])},
'qr-not-detected':{'ru':('QR-код не распознаётся на Mac: что проверить','Чаще всего помогают масштаб, целый код и небольшая рамка вокруг.', [('Выделите QR целиком','Не обрезайте угловые квадраты и белое поле по краям. ScreenQR ищет QR только внутри выделенной области. Если за её пределами осталась часть кода, распознавание может не сработать.'),('Увеличьте исходник','Увеличьте масштаб страницы, PDF или картинки. Лучше использовать исходное изображение, а не многократно пересжатый скриншот. Полностью видимый чёткий QR обычно легче распознаётся.'),('Проверьте тип кода','ScreenQR распознаёт QR, а не все виды штрихкодов. Полосатый товарный штрихкод, Data Matrix и повреждённый декоративный код могут не дать результата.'),('Разделите несколько кодов','Если на экране много QR, выделите один. При распознавании нескольких приложение показывает несколько результатов, и их можно открыть или скопировать отдельно.'),('Отличайте ошибку доступа','Сообщение о снимке экрана означает проблему захвата или разрешения. «QR-код не найден» означает, что снимок получен, но распознавание не нашло QR. В первом случае откройте инструкцию доступа.')]),'en':('QR code not scanning on Mac: what to check','Try a larger, complete code with a small margin around it.', [('Select the whole QR','Keep all corner squares and the quiet margin around the code. ScreenQR searches only inside your selected area. Cutting off a part of the QR can prevent recognition.'),('Enlarge the source','Zoom in on the page, PDF or image. Prefer the original image over a repeatedly compressed screenshot. A complete, sharp code is usually easier to read.'),('Check the code type','ScreenQR reads QR codes, rather than every barcode format. A striped product barcode, Data Matrix or damaged decorative code may not produce a result.'),('Separate multiple codes','If several codes are visible, select one. When multiple QR codes are recognized, the app shows separate results that you can open or copy individually.'),('Distinguish permission errors','A screen capture error means capture or access failed. No QR code found means the image was captured but recognition found no QR. For capture errors, read the permission guide.')])}}
def route(lang,path=''):return ('en/' if lang=='en' else '')+path
def header(lang,path=''):
 c=COPY[lang];home=BASE+route(lang);other=BASE+route('en' if lang=='ru' else 'ru',path)
 return f'<a class="skip" href="#main">{c["skip"]}</a><nav aria-label="Main"><a class="brand" href="{home}"><img src="{BASE}assets/icon.png" width="42" height="42" alt="">ScreenQR</a><div class="navlinks"><a class="optional" href="{home}#how">{c["nav"][0]}</a><a class="optional" href="{home}#install">{c["nav"][1]}</a><a href="{other}" lang="{"en" if lang=="ru" else "ru"}">{c["lang"]}</a><a href="{REPO}">{c["source"]} ↗</a></div></nav>'
def guide_links(lang):return ''.join(f'<a href="{BASE+route(lang,"guides/"+slug+"/")}">{escape(value[lang][0])} <span aria-hidden="true">↗</span></a>' for slug,value in GUIDES.items())
def footer(lang):
 c=COPY[lang];return f'<footer><span>ScreenQR · {c["footer"]}</span><div><a href="{BASE+route(lang,"privacy/")}">{c["privacyLink"]}</a><a href="{REPO}/issues">{"Обратная связь" if lang=="ru" else "Feedback"}</a><a href="{REPO}/blob/main/LICENSE">MIT</a></div></footer>'
def write(lang,path,title,description,body,kind='WebPage'):
 rel=route(lang,path); url=BASE+rel;other=BASE+route('en' if lang=='ru' else 'ru',path)
 schema={'@context':'https://schema.org','@type':kind,'name':title,'description':description,'url':url,'inLanguage':lang}
 if kind=='SoftwareApplication':schema.update(applicationCategory='UtilitiesApplication',operatingSystem='macOS 14+',softwareVersion=VERSION,downloadUrl=DOWNLOAD,offers={'@type':'Offer','price':'0','priceCurrency':'USD'})
 html=f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="{lang}" href="{url}"><link rel="alternate" hreflang="{"en" if lang=="ru" else "ru"}" href="{other}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/social.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{BASE}assets/icon.png"><link rel="stylesheet" href="{BASE}assets/site.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False).replace("<","\\u003c")}</script><script src="{BASE}assets/site.js" defer></script></head><body>{header(lang,path)}{body}{footer(lang)}</body></html>'
 target=OUT/rel/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html);return url
urls=[]
for lang,c in COPY.items():
 steps=''.join(f'<div><span class="number">{i+1}</span><h3>{a}</h3><p>{b}</p></div>' for i,(a,b) in enumerate(c['steps']))
 inputs=''.join(f'<h3>{a}</h3><p>{b}</p>' for a,b in c['inputs'])
 faq=''.join(f'<details><summary>{a}</summary><p>{b}</p></details>' for a,b in c['faq'])
 install=''.join(f'<li>{s}</li>' for s in c['install'])
 body=f'''<main id="main"><div class="hero"><div><div class="eyebrow">{c['eyebrow']}</div><h1>{c['h1']}<br><span>{c['h2']}</span></h1><p class="lead">{c['lead']}</p><div class="actions"><a class="button primary" href="{DOWNLOAD}">↓ {c['download']}</a><a class="button" href="#demo">{c['demo']}</a></div><div class="fine">{c['meta']}</div><div class="fine">{c['beta']} · <a href="{REPO}/releases/tag/v0.2.0-beta">{"О выпуске" if lang=='ru' else 'Release notes'}</a></div></div><div id="demo"><div class="stage" role="group" aria-label="{c['demoLabel']}"><div class="menubar"><span>● &nbsp; ScreenQR</span><button class="scanicon" data-scan aria-label="{c['demo']}" aria-expanded="true" aria-controls="demo-result">▦</button></div><div class="sample"><strong>{c['sample']}</strong><img src="{BASE}assets/qr.png" width="150" height="150" alt="{c['sampleNote']}"><small>{c['sampleNote']}</small></div><div class="selection"></div><div class="result" data-result id="demo-result"><div class="status">✓ {c['found']}</div><span class="domain">example.com</span><div class="address">https://example.com/screenqr-test</div><a class="button primary" href="https://example.com/screenqr-test" target="_blank" rel="noopener">{c['open']} ↗</a> <button class="button" data-copy>{c['copy']}</button></div></div><div class="demo-note">{c['demoNote']}</div></div></div><section id="how"><div class="eyebrow">{"Три простых шага" if lang=='ru' else 'Three simple steps'}</div><h2>{c['stepsTitle']}</h2><div class="steps">{steps}</div></section><section><div class="columns"><div><h2>{c['inputsTitle']}</h2>{inputs}</div><div class="privacy"><span aria-hidden="true">◉</span><h3>{c['privacyTitle']}</h3><p>{c['privacyText']}</p><a href="{BASE+route(lang,'privacy/')}">{c['privacyLink']} ↗</a></div></div></section><section id="install" class="install"><div class="eyebrow">{"Начать пользоваться" if lang=='ru' else 'Get started'}</div><h2>{c['installTitle']}</h2><div class="columns"><ol>{install}</ol><div><div class="note">{c['installNote']}</div><a href="{BASE+route(lang,'guides/screen-recording-permission/')}">{c['installLink']} ↗</a><p class="fine"><a href="{REPO}/releases/download/v0.2.0-beta/ScreenQR-0.2.0-macos.zip">ZIP</a> · <a href="{REPO}/releases/download/v0.2.0-beta/ScreenQR-0.2.0-macos.sha256">SHA-256</a></p></div></div></section><section id="guides"><h2>{c['guidesTitle']}</h2><div class="guides">{guide_links(lang)}</div></section><section><h2>{c['faqTitle']}</h2>{faq}</section><section><div class="columns"><div><div class="eyebrow">ProfileDock</div><h2>{c['relatedTitle']}</h2></div><div><p>{c['relatedText']}</p><a class="button" href="https://kunilingvistador.github.io/ProfileDock/{'en/' if lang=='en' else ''}">{c['relatedLink']} ↗</a></div></div></section></main>'''
 urls.append(write(lang,'',c['title'],c['description'],body,'SoftwareApplication'))
 for slug,values in GUIDES.items():
  title,desc,sections=values[lang]; content=''.join(f'<h2>{escape(a)}</h2><p>{escape(b)}</p>' for a,b in sections)
  article=f'<main id="main"><article class="article"><div class="eyebrow">ScreenQR · {c["nav"][2]}</div><h1>{title}</h1><p class="lead">{desc}</p>{content}<a class="button primary" href="{DOWNLOAD}">↓ {c["download"]}</a><p class="fine">{c["meta"]} · {c["beta"]}</p><div class="related"><h2>{c["guidesTitle"]}</h2>{guide_links(lang)}</div></article></main>'
  urls.append(write(lang,'guides/'+slug+'/',title+' — ScreenQR',desc,article))
 if lang=='ru':
  title='ScreenQR: данные и разрешения';desc='Что ScreenQR считывает на Mac, зачем нужен доступ к экрану и куда попадают результаты.';parts=[('Экран и изображения','Во время сканирования ScreenQR временно получает снимки подключённых экранов, затем распознаёт QR в выбранной области. Снимки остаются в памяти приложения, не записываются им на диск и не отправляются на сервер. Для файлов и буфера используются изображения, которые вы выбрали сами.'),('Результаты и настройки','История сканирований не сохраняется. Последний результат виден в карточке до её закрытия или следующего результата. Настройки горячей клавиши и компактной карточки сохраняются в macOS. При копировании текст попадает в системный буфер: его могут читать другие приложения и функции синхронизации буфера, если они включены.'),('Открытие ссылки','Только HTTP(S)-адреса без встроенного логина и пароля получают кнопку открытия. Переход выполняется браузером по умолчанию после нажатия. Сайт назначения получает обычный запрос вашего браузера. ScreenQR не проверяет безопасность или репутацию сайта.'),('Разрешения','Запись экрана нужна только для захвата экрана. Приложение не записывает звук, не использует камеру и не требует Accessibility. Разрешение macOS шире выбранной области: система позволяет приложению получать снимки экранов, а выделение ограничивает последующее распознавание.'),('Сайт и загрузки','Этот сайт и исходный код размещены на GitHub. На сайте нет аналитических скриптов, рекламы или собственных cookies. GitHub обрабатывает запросы к сайту и загрузкам по своей политике. Встроенная демонстрация использует только example.com и открывает его по вашему нажатию.'),('Обратная связь','Не прикладывайте к публичным GitHub issues снимки с личными данными, паролями Wi-Fi или секретными QR. Используйте пример, который можно безопасно показать.')]
 else:
  title='ScreenQR: data and permissions';desc='What ScreenQR reads on your Mac, why screen access is needed and where results go.';parts=[('Screens and images','During a screen scan, ScreenQR temporarily captures connected displays, then reads QR codes inside the selected area. The app keeps screenshots in memory, does not save them to disk and does not upload them. For image files and clipboard, it reads the images you choose.'),('Results and preferences','No scan history is saved. The last result stays in its card until closed or replaced. Shortcut and compact-card preferences are saved by macOS. Copying places text in the system clipboard, where other applications or clipboard synchronization features may access it.'),('Opening a link','Only HTTP(S) addresses without embedded credentials receive an Open button. Your default browser opens the URL after your click. The destination receives a normal browser request. ScreenQR does not check website safety or reputation.'),('Permissions','Screen Recording is needed only for screen capture. The app does not record audio, use a camera or require Accessibility. The macOS permission is broader than your selection: it allows display capture, while selection limits subsequent QR recognition.'),('Website and downloads','The website and source code are hosted by GitHub. The site has no analytics scripts, ads or custom cookies. GitHub processes site and download requests under its own policies. The interactive example links only to example.com after you click.'),('Feedback','Do not attach screenshots containing personal information, Wi-Fi passwords or secret QR codes to public GitHub issues. Use a safe example instead.')]
 body='<main id="main"><article class="article"><div class="eyebrow">ScreenQR</div><h1>'+title+'</h1><p class="lead">'+desc+'</p>'+''.join(f'<h2>{a}</h2><p>{b}</p>' for a,b in parts)+f'<p><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a></p><a class="button" href="{BASE+route(lang)}">ScreenQR ↗</a></article></main>'
 urls.append(write(lang,'privacy/',title,desc,body))
